INDEX `idx_cpr_deleted`(`deleted` ASC) USING BTREE,
INDEX `idx_cpr_is_enabled`(`is_enabled` ASC) USING BTREE,
INDEX `idx_cpr_permission_type`(`permission_type` ASC) USING BTREE,
INDEX `idx_cpr_priority`(`priority` ASC) USING BTREE,
INDEX `idx_cpr_table_name`(`table_name` ASC) USING BTREE,
INDEX `idx_cpr_tenant_id`(`tenant_id` ASC) USING BTREE,
