INDEX `idx_dpr_app_id`(`app_id` ASC) USING BTREE,
INDEX `idx_dpr_data_scope`(`data_scope` ASC) USING BTREE,
INDEX `idx_dpr_deleted`(`deleted` ASC) USING BTREE,
