-- lrcore_cloud.sys_permission DDL
DROP TABLE IF EXISTS `lrcore_cloud`.`sys_permission`;
CREATE TABLE `lrcore_cloud`.`sys_permission` (`id` BIGINT NOT NULL Comment '主键ID',
`app_id` BIGINT NOT NULL Comment '所属应用ID（关联sys_app表）',
`pid` BIGINT NOT NULL DEFAULT 0 Comment '父权限ID，0代表根节点',
`type` TINYINT NOT NULL Comment '权限类型：0=目录 1=菜单 2=按钮 3=接口',
`name` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL Comment '路由唯一名称（必填，英文首字母大写）',
`title` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '组件标题',
`perm_code` VARCHAR(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL Comment '权限唯一编码',
`path` VARCHAR(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '路由访问路径 纯字符串（不带/，代表子路由）',
`component` VARCHAR(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '页面组件文件路径',
`redirect` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '重定向地址 如二级地址访问/doc/innernal-doc',
`req_method` VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '请求方法 get|post|put|option|delete',
`req_url` VARCHAR(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '接口|外部访问请求URL',
`icon` VARCHAR(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '菜单图标',
`sort` INT NULL DEFAULT 1 Comment '菜单排序',
`status` TINYINT NULL DEFAULT 1 Comment '状态：0=禁用 1=启用',
`hidden` TINYINT NULL DEFAULT 0 Comment '控制侧边栏是否隐藏该菜单',
`keep_live` TINYINT NULL Comment '是否开启页面缓存（标签页关闭前保留表单 / 查询条件）',
`always_show` TINYINT NULL Comment '是否总是折叠菜单',
`build_in` TINYINT NULL DEFAULT 0 Comment '是否内置(0-否 1-是)',
`version_num` INT NOT NULL DEFAULT 1 Comment '版本号',
`has_column_permission` TINYINT NOT NULL DEFAULT 0 Comment '是否包含字段级权限（0=否 1=是）',
`tenant_id` BIGINT NULL Comment '租户ID',
`create_user_id` BIGINT NULL Comment '创建者ID',
`update_user_id` BIGINT NULL Comment '更新者ID',
`create_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP Comment '创建时间',
`update_time` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) Comment '更新时间',
`remark` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' Comment '备注',
`deleted` TINYINT NOT NULL DEFAULT 0 Comment '删除标记：0=未删除 1=已删除',
INDEX `idx_perm_app_id`(`app_id` ASC) USING BTREE comment '应用ID索引',
INDEX `idx_perm_app_id_type`(`app_id` ASC,`type` ASC) USING BTREE,
INDEX `idx_perm_code_type`(`perm_code` ASC,`type` ASC) USING BTREE,
INDEX `idx_perm_parent_id`(`pid` ASC) USING BTREE comment '父权限ID索引',
INDEX `idx_perm_parent_id_type`(`pid` ASC,`type` ASC) USING BTREE,
INDEX `idx_perm_tenant_id`(`tenant_id` ASC) USING BTREE comment '租户ID索引',
