`remark` VARCHAR(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL Comment '备注',
`build_in` TINYINT NULL DEFAULT 0 Comment '是否内置(0-否 1-是)',
`deleted` TINYINT NOT NULL DEFAULT 0 Comment '删除标识（0未删除 1已删除）',
INDEX `idx_t_pdbi_category`(`category` ASC) USING BTREE,
INDEX `idx_t_pdbi_key`(`key` ASC) USING BTREE,
INDEX `idx_t_pdbi_status`(`status` ASC) USING BTREE,
PRIMARY KEY (`id`)) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic COMMENT = '流程定义基础信息表';
-- lrcore_cloud.v_data_permission_rules_application DDL
CREATE OR REPLACE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `lrcore_cloud`.`v_data_permission_rules_application` AS select `sdpr`.`id` AS `id`,`sdpr`.`rule_name` AS `rule_name`,`sdpr`.`rule_code` AS `rule_code`,`sdpr`.`rule_type` AS `rule_type`,`sdpr`.`target_table` AS `target_table`,`sdpr`.`data_scope` AS `data_scope`,`sdpr`.`priority` AS `priority`,`sdpr`.`is_enabled` AS `is_enabled`,`sdpr`.`tenant_id` AS `tenant_id`,`sdpr`.`app_id` AS `app_id`,(case `sdpr`.`rule_type` when 1 then '行级权限' when 2 then '字段级权限' when 3 then '数据范围权限' when 4 then '自定义SQL权限' end) AS `rule_type_name`,(case `sdpr`.`data_scope` when 1 then '全部数据' when 2 then '本企业数据' when 3 then '本部门数据' when 4 then '本部门及下级数据' when 5 then '本人数据' when 6 then '自定义' end) AS `data_scope_name` from `lrcore_cloud`.`sys_data_permission_rule` `sdpr` where (`sdpr`.`deleted` = 0) order by `sdpr`.`priority`;
-- lrcore_cloud.v_permission_verification_stats DDL
CREATE OR REPLACE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `lrcore_cloud`.`v_permission_verification_stats` AS select `lrcore_cloud`.`sys_permission_audit_log`.`app_id` AS `app_id`,`lrcore_cloud`.`sys_permission_audit_log`.`tenant_id` AS `tenant_id`,count(0) AS `total_verifications`,sum((case when (`lrcore_cloud`.`sys_permission_audit_log`.`response_status` = 0) then 1 else 0 end)) AS `successful_verifications`,sum((case when (`lrcore_cloud`.`sys_permission_audit_log`.`response_status` = 1) then 1 else 0 end)) AS `failed_verifications`,avg(`lrcore_cloud`.`sys_permission_audit_log`.`execution_time`) AS `avg_execution_time`,max(`lrcore_cloud`.`sys_permission_audit_log`.`execution_time`) AS `max_execution_time`,min(`lrcore_cloud`.`sys_permission_audit_log`.`execution_time`) AS `min_execution_time`,avg((case when (`lrcore_cloud`.`sys_permission_audit_log`.`response_status` = 0) then `lrcore_cloud`.`sys_permission_audit_log`.`execution_time` else NULL end)) AS `avg_success_time`,avg((case when (`lrcore_cloud`.`sys_permission_audit_log`.`response_status` = 1) then `lrcore_cloud`.`sys_permission_audit_log`.`execution_time` else NULL end)) AS `avg_fail_time` from `lrcore_cloud`.`sys_permission_audit_log` where ((`lrcore_cloud`.`sys_permission_audit_log`.`deleted` = 0) and (`lrcore_cloud`.`sys_permission_audit_log`.`audit_type` = 4)) group by `lrcore_cloud`.`sys_permission_audit_log`.`app_id`,`lrcore_cloud`.`sys_permission_audit_log`.`tenant_id`;
-- lrcore_cloud.v_user_column_permissions DDL
CREATE OR REPLACE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `lrcore_cloud`.`v_user_column_permissions` AS select `ucp`.`user_id` AS `user_id`,`ucp`.`table_name` AS `table_name`,`ucp`.`column_name` AS `column_name`,(case when (`ucp`.`is_override` = 1) then `ucp`.`permission_type` else coalesce(`rcp`.`permission_type`,3) end) AS `permission_type`,`ucp`.`tenant_id` AS `tenant_id`,`ucp`.`app_id` AS `app_id`,`ucp`.`status` AS `status` from (`lrcore_cloud`.`sys_user_column_permission` `ucp` left join `lrcore_cloud`.`sys_role_column_permission` `rcp` on(((`ucp`.`table_name` = `rcp`.`table_name`) and (`ucp`.`column_name` = `rcp`.`column_name`) and `rcp`.`role_id` in (select `lrcore_cloud`.`sys_user_role`.`role_id` from `lrcore_cloud`.`sys_user_role` where ((`lrcore_cloud`.`sys_user_role`.`user_id` = `ucp`.`user_id`) and (`lrcore_cloud`.`sys_user_role`.`deleted` = 0))) and (`rcp`.`tenant_id` = `ucp`.`tenant_id`) and (`rcp`.`status` = 0) and (`rcp`.`deleted` = 0)))) where ((`ucp`.`deleted` = 0) and (`ucp`.`status` = 0)) union select `ur`.`user_id` AS `user_id`,`rcp`.`table_name` AS `table_name`,`rcp`.`column_name` AS `column_name`,`rcp`.`permission_type` AS `permission_type`,`rcp`.`tenant_id` AS `tenant_id`,`rcp`.`app_id` AS `app_id`,`rcp`.`status` AS `status` from (`lrcore_cloud`.`sys_user_role` `ur` join `lrcore_cloud`.`sys_role_column_permission` `rcp` on(((`ur`.`role_id` = `rcp`.`role_id`) and (`ur`.`tenant_id` = `rcp`.`tenant_id`) and (`rcp`.`status` = 0) and (`rcp`.`deleted` = 0)))) where ((`ur`.`deleted` = 0) and (not exists(select 1 from `lrcore_cloud`.`sys_user_column_permission` `ucp` where ((`ucp`.`user_id` = `ur`.`user_id`) and (`ucp`.`table_name` = `rcp`.`table_name`) and (`ucp`.`column_name` = `rcp`.`column_name`) and (`ucp`.`tenant_id` = `rcp`.`tenant_id`) and (`ucp`.`deleted` = 0)))));
-- lrcore_cloud.add_column_if_not_exists DDL
DROP PROCEDURE IF EXISTS `lrcore_cloud`.`add_column_if_not_exists`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `add_column_if_not_exists`(IN table_name VARCHAR(100),
    IN column_name VARCHAR(100),
    IN column_definition TEXT)
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME = table_name
        AND COLUMN_NAME = column_name
    ) THEN
        SET @sql = CONCAT('ALTER TABLE ', table_name, ' ADD COLUMN ', column_name, ' ', column_definition);
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END$$
DELIMITER ;
-- lrcore_cloud.add_index_if_not_exists DDL
DROP PROCEDURE IF EXISTS `lrcore_cloud`.`add_index_if_not_exists`;
DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `add_index_if_not_exists`(IN table_name VARCHAR(100),
    IN index_name VARCHAR(100),
    IN index_definition TEXT)
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.STATISTICS
        WHERE TABLE_SCHEMA = DATABASE()
        AND TABLE_NAME = table_name
        AND INDEX_NAME = index_name
    ) THEN
        SET @sql = CONCAT('CREATE INDEX ', index_name, ' ON ', table_name, ' ', index_definition);
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
    END IF;
END$$
DELIMITER ;
